begin read only;
-- Expected: every Registry identity exists, no foreign leaf/Worker/publication, helper hash matches.
select '318473c0-46ea-55e7-ab06-53520ea2373f' question_id,exists(select 1 from public.essay_questions where id='318473c0-46ea-55e7-ab06-53520ea2373f' and essay_exam_id='3643b295-3b63-5b77-bd1b-d3ce68de4885') registry_matches,(select count(*) from public.math_subproblems where essay_question_id='318473c0-46ea-55e7-ab06-53520ea2373f') existing_leaves,exists(select 1 from math_private.task20_hanyang_source_pages where question_id='318473c0-46ea-55e7-ab06-53520ea2373f') existing_worker;
select '6c7d310f-d055-595c-8aa5-49d901b19f36' question_id,exists(select 1 from public.essay_questions where id='6c7d310f-d055-595c-8aa5-49d901b19f36' and essay_exam_id='3643b295-3b63-5b77-bd1b-d3ce68de4885') registry_matches,(select count(*) from public.math_subproblems where essay_question_id='6c7d310f-d055-595c-8aa5-49d901b19f36') existing_leaves,exists(select 1 from math_private.task20_hanyang_source_pages where question_id='6c7d310f-d055-595c-8aa5-49d901b19f36') existing_worker;
select 'ee907ec5-88f2-5097-83be-9b8c9a03ec93' question_id,exists(select 1 from public.essay_questions where id='ee907ec5-88f2-5097-83be-9b8c9a03ec93' and essay_exam_id='3643b295-3b63-5b77-bd1b-d3ce68de4885') registry_matches,(select count(*) from public.math_subproblems where essay_question_id='ee907ec5-88f2-5097-83be-9b8c9a03ec93') existing_leaves,exists(select 1 from math_private.task20_hanyang_source_pages where question_id='ee907ec5-88f2-5097-83be-9b8c9a03ec93') existing_worker;
select md5(pg_get_functiondef('math_private.hanyang_worker_references(jsonb)'::regprocedure)) worker_md5;
select r,has_table_privilege(r,'math_private.task20_hanyang_source_pages','SELECT') source_read,has_function_privilege(r,'math_private.hanyang_worker_references(jsonb)','EXECUTE') worker_execute from unnest(array['anon','authenticated']) r;
select 'essay_attempts' name,md5(coalesce(string_agg(md5(to_jsonb(x)::text),'' order by id),'')) digest from public.essay_attempts x union all select 'essay_evaluations' name,md5(coalesce(string_agg(md5(to_jsonb(x)::text),'' order by id),'')) digest from public.essay_evaluations x union all select 'credit_transactions' name,md5(coalesce(string_agg(md5(to_jsonb(x)::text),'' order by id),'')) digest from public.credit_transactions x;
commit;
